window.docContents[255].resolve({"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Finding-Loop-Invariants--Exercise___-Minimum":{"contents":"\n\n\n\nFill in decorations for the following program and prove them\ncorrect.  As with factorial, be careful about mathematical\nreasoning involving natural numbers, especially subtraction.Lean functions can be applied directly inside assertions.  For\nexample, the minimum of a and b can be written Nat.min a b.def minimumDec (a b : Nat) : Decorated where\n  pre := ({{ True }})\n  body := dcom {\n    ↠ {{ solution!({{ 0 + Nat.min a b = Nat.min a b }}) }}\n    X := ~(Aexp.num a) {{\n      solution!({{ 0 + Nat.min X b = Nat.min a b }})\n    }};\n    Y := ~(Aexp.num b) {{\n      solution!({{ 0 + Nat.min X Y = Nat.min a b }})\n    }};\n    Z := 0 {{\n      solution!({{ Z + Nat.min X Y = Nat.min a b }})\n    }};\n    while (X ≠ 0 ∧ Y ≠ 0) do\n      {{ solution!({{\n        Z + Nat.min X Y = Nat.min a b ∧ (¬ X = 0 ∧ ¬ Y = 0)\n      }}) }}\n      ↠ {{ solution!({{\n        Z + 1 + Nat.min (X - 1) (Y - 1) = Nat.min a b\n      }}) }}\n      X := X - 1 {{\n        solution!({{\n          Z + 1 + Nat.min X (Y - 1) = Nat.min a b\n        }})\n      }};\n      Y := Y - 1 {{\n        solution!({{ Z + 1 + Nat.min X Y = Nat.min a b }})\n      }};\n      Z := Z + 1 {{\n        solution!({{ Z + Nat.min X Y = Nat.min a b }})\n      }}\n    end\n      {{ solution!({{\n        Z + Nat.min X Y = Nat.min a b ∧\n        ¬ (¬ X = 0 ∧ ¬ Y = 0)\n      }}) }}\n    ↠ {{ Z = Nat.min a b }}\n  }\nHIDE:* The first implication follows by substitution and arithmetic.* For the second, the loop guard says that X and Y are nonzero.\n  Thus Nat.min X Y is nonzero, and\n  Nat.min (X - 1) (Y - 1) = Nat.min X Y - 1. Natural-number\n  subtraction therefore does not truncate the result to zero, and\n  Z + 1 + Nat.min (X - 1) (Y - 1) can be rewritten as\n  Z + Nat.min X Y.* For the third, the negated loop guard says that at least one of X\n  and Y is zero, so Nat.min X Y = 0.theorem minimum_correct (a b : Nat) :\n    (minimumDec a b).OuterTripleValid := by\n  solution!\n    simp only [minimumDec]\n    verify\n\n\n","context":"Hoare Logic\u0009Hoare2: Hoare Logic, Part II\u0009Finding Loop Invariants","header":"6.3.7. Exercise: Minimum","id":"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Finding-Loop-Invariants--Exercise___-Minimum"}});